import { Component, ChangeDetectorRef } from '@angular/core';
import { HeaderService } from '../../../../core/services/header/header.service';
import { CasedetailService } from '../../../../shared/services/casedetail/casedetail.service';
import { ActivatedRoute } from '@angular/router';
import { MatSelectModule } from '@angular/material/select';
import { MatFormFieldModule } from '@angular/material/form-field';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../shared/components/button/button.component';
import { CommonModule } from '@angular/common';
import { ProgressComponent } from '../../../../shared/components/progress/progress.component';
import { EmptyComponent } from '../../../../shared/components/empty/empty.component';
import { SkeletonComponent } from '../../../../shared/components/skeleton/skeleton.component';
import { ExportService } from '../../../services/export/export.service';
import { Subscription } from 'rxjs';
import { SocketService } from '../../../../core/services/socket/socket.service';
import { exportSocketRes } from '../../../interfaces/export.interface';
import { environment } from '../../../../../environments/environment';
import { TostbarService } from '../../../../core/services/tost/tostbar.service';
import { FormsModule } from '@angular/forms';
import { CdkVirtualScrollViewport, ScrollingModule } from '@angular/cdk/scrolling';
import { MatMenuModule } from '@angular/material/menu';
import { BytesPipe } from '../../../../shared/pips/bytes/bytes.pipe';
import { TabletruncComponent } from '../../../../shared/components/myfiles/tabletrunc/tabletrunc.component';
import { UserPermissionService } from '../../../../shared/services/user-permission/user-permission.service';

@Component({
  selector: 'app-export',
  standalone: true,
  imports: [CommonModule, FormsModule, SkeletonComponent, MatSelectModule, MatFormFieldModule,
    IconComponent, ButtonComponent, ProgressComponent, EmptyComponent, ScrollingModule, MatMenuModule, BytesPipe, TabletruncComponent],
  templateUrl: './export.component.html',
  styleUrl: './export.component.scss'
})
export class ExportComponent {
  nCaseid: string;
  loading: boolean = false;
  loglist: any = [];
  cSortBy: string = 'N';

  // downloadPath: string = `${environment.cloudUrl}${environment.downloadpath}`;
  socketSubscription: Subscription;
  constructor(private hs: HeaderService, private cDetailS: CasedetailService, private route: ActivatedRoute,
    private exportservice: ExportService, private ss: SocketService, private cdr: ChangeDetectorRef
    , private tost: TostbarService, private userPermissions: UserPermissionService
  ) {

    var params = this.route.snapshot.params;
    params = JSON.parse(atob(params["id"]));
    this.nCaseid = params && params["id"] ? params["id"] : 0;

    this.socketSubscription = this.ss.getFileExports().subscribe((res: any) => {
      console.log('export', res);
      const data: exportSocketRes = res?.data?.data || [];
      if (data && data.nCaseid == this.nCaseid) {
        console.log('export data', data);

        if (data.cStatus == 'P') {
          let obj;

          if (data.cType == 'S') {
            obj = this.loglist.find(a => a.nExportid === data.nExportid);
          } else {
            obj = this.loglist.find(a => a.nEDid == data.nEDid);
          }

          console.log('obj', obj, data, this.loglist);
          if (obj) {
            if (data["finalPath"] && data["finalPath"] != "") {
              obj.cPath = data.finalPath;
            }

            obj.comp_progres = data.comp_progres?.toFixed();
            obj.total_prog = data.total_prog;
            obj.cStatus = data.cStatus;
          }
          this.cdr.detectChanges();
        } else if (data.cStatus == 'C') {
          let obj = this.loglist.find(a => a.nExportid === data.nExportid);
          if (data.cType == 'S') {
            obj = this.loglist.find(a => a.nExportid === data.nExportid);
          } else {
            obj = this.loglist.find(a => a.nEDid == data.nEDid);
          }

          obj.cStatus = 'C';
          obj.cPath = data.finalPath;
        }
        else if (data.cStatus == 'F') {
          // console.log('data', data);
          if (data.cType == 'S') {
            const obj = this.loglist.find(a => a.nExportid === data.nExportid);
            if (obj) {
              obj.cStatus = 'F';
            }
          } else {
            const objArr = this.loglist.filter(a => a.nExportid === data.nExportid);
            if (objArr && objArr.length) {
              objArr.forEach(obj => obj.cStatus = 'F');
            }
          }
        }
      }
    })
    userPermissions.userPermissionList(this.nCaseid);

  }

  ngOnDestroy(): void {
    //Called once, before the instance is destroyed.
    //Add 'implements OnDestroy' to the class.
    this.socketSubscription.unsubscribe();
  }

  async ngOnInit() {
    this.hs.nCaseid = this.nCaseid;
    this.hs.Casedetail = await this.cDetailS.getCaseInfo(this.nCaseid);
    this.getexportList()
    this.cdr.detectChanges();

  }


  getexportList() {
    this.loading = true;
    this.exportservice.getExportlist(this.nCaseid, null, null, this.cSortBy).then((data) => {
      this.loglist = data;
      this.loading = false;
    });
  }


  fetchinfo(obj) {
    this.loading = true;
    this.exportservice.getExportlist(this.nCaseid, (obj.nEDid ? obj.nEDid : 0), obj.nExportid, this.cSortBy).then((data) => {
      if (data.length) {
        obj = data[0];
      }
    });
  }

  delete(x) {
    this.exportservice.deleteExport(this.nCaseid, x.nEDid ? x.nEDid : 0, x.nExportid, x.cType).then((data) => {
      if (data) {
        this.loglist = this.loglist.filter(a => x.cType == 'S' ? a.nExportid !== x.nExportid : a.nEDid !== x.nEDid);
        this.cdr.detectChanges();
      }
    });
  }

  clearall() {
    this.loading = true;
    this.exportservice.clearallExport(this.nCaseid).then((data) => {
      if (data) {
        this.loglist = [];
        this.cdr.detectChanges();
      }
    });
  }

  async downloadURI(uri, name) {
    const fileName = `${uri}`; // The file name you want to download
    // this.exportservice.downloadFile(fileName).subscribe(
    //   (blob) => {
    //     const a = document.createElement('a');
    //     const objectUrl = URL.createObjectURL(blob);
    //     a.href = objectUrl;
    //     a.download = name;
    //     a.click();
    //     URL.revokeObjectURL(objectUrl);
    //   },
    //   (error) => {
    //     console.error('Download error:', error);
    //     this.tost.error('Failed to download');
    //   }
    // );

    this.exportservice.downloadFile(fileName, name);
  }
  async retry(x: any) {
    if (x.cType == 'S') {
      const obj = this.loglist.find(a => a.nExportid === x.nExportid);
      if (obj) {
        obj.cStatus = 'P';
        obj.total_prog = 0;
        obj.comp_progres = 0;
      }
    } else {
      const objArr = this.loglist.filter(a => a.nExportid === x.nExportid);
      if (objArr && objArr.length) {
        objArr.forEach(obj => { obj.cStatus = 'P'; obj.total_prog = 0; obj.comp_progres = 0; });
      }
    }
    const res = await this.exportservice.retryExport(x.nExportid)
    if (res) {
      x.exportStatus = 'P';
      x.comp_progres = 0;
    }
    this.cdr.detectChanges();
  }
}
